void postorder(TreeNode* root, vector<int>& result) {

    if (!root) return;

    postorder(root->left, result);   // 1. Go left
    postorder(root->right, result);  // 2. Go right
    result.push_back(root->val);     // 3. Visit root LAST
}

vector<int> postorder(TreeNode* root) {

    vector<int> result;
    if (!root) return result;

    stack<TreeNode*> st;
    st.push(root);

    while (!st.empty()) {
        TreeNode* node = st.top(); st.pop();

        result.push_back(node->val);    // collect root first

        // push LEFT before RIGHT (opposite of preorder)
        if (node->left)  st.push(node->left);
        if (node->right) st.push(node->right);
    }

    reverse(result.begin(), result.end()); // reverse at end

    return result;
    // Preorder gave: Root→Right→Left
    // Reversed gives: Left→Right→Root = Postorder ✓
}

int height(TreeNode* root) {

    if (!root)
        return -1;  // base case: null node has height -1

    int leftHeight = height(root->left);    // get left subtree height
    int rightHeight = height(root->right);  // get right subtree height

    return 1 + max(leftHeight, rightHeight); // compute current node's height
}
